import { MANUAL_IMAGES } from "./manual-images";

export function getGallery(slug: string): GalleryImage[] {
  return [
    ...(IMAGE_GALLERY[slug] ?? []),
    ...(MANUAL_IMAGES[slug] ?? []),
  ];
}
